/** Dedicated host-only room display. The code is generated by the LAN server,
 * never fabricated in the browser, and shown only AFTER the server accepts /lan/host.
 */
import {normalizeRoomCode, whatsappShareUrl} from './lan-v5.js';

async function copyText(value, doc, fallback) {
  if (!value) return false;
  try {
    if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(value); return true; }
  } catch (_) {}
  const textarea=doc.createElement('textarea');
  textarea.value=value;textarea.readOnly=true;
  textarea.style.position='fixed';textarea.style.top='-9999px';
  doc.body.appendChild(textarea);textarea.select();
  let copied=false;
  try {copied=Boolean(doc.execCommand?.('copy'));} catch (_) {}
  textarea.remove();
  if (!copied && fallback) {fallback.focus();fallback.select?.();}
  return copied;
}

export function createOwnRoomPanel(doc=document) {
  const card=doc.getElementById('bronxOwnRoom');
  const codeNode=doc.getElementById('bronxOwnRoomCode');
  const hint=doc.getElementById('bronxOwnRoomHelp');
  const actions=doc.getElementById('bronxOwnRoomActions');
  const copyCode=doc.getElementById('bronxOwnCopyCode');
  const copyLink=doc.getElementById('bronxOwnCopyLink');
  const share=doc.getElementById('bronxOwnWhatsapp');
  const urlInput=doc.getElementById('bronxOwnRoomLink');
  if ([card,codeNode,hint,actions,copyCode,copyLink,share,urlInput].some(x=>!x))
    throw Error('Faltam elementos para mostrar o código da SUA sala.');
  let currentCode='';let currentUrl='';
  copyCode.addEventListener('click',async()=>{
    const ok=await copyText(currentCode,doc,urlInput);
    copyCode.textContent=ok?'CÓDIGO COPIADO':'SELECIONE O CÓDIGO';
    if(!ok && currentCode){const sel=doc.createRange();sel.selectNodeContents(codeNode);doc.getSelection()?.removeAllRanges();doc.getSelection()?.addRange(sel);}
  });
  copyLink.addEventListener('click',async()=>{
    const ok=await copyText(currentUrl,doc,urlInput);
    copyLink.textContent=ok?'LINK COPIADO':'SELECIONE O LINK';
  });
  function show({code,url='',warning=''}) {
    const normalized=normalizeRoomCode(code);
    if(!normalized)throw Error('O servidor não devolveu um código de sala válido.');
    currentCode=normalized;currentUrl=url;
    codeNode.textContent=normalized;
    codeNode.setAttribute('aria-label','Código da sua sala: '+normalized.split('').join(' '));
    hint.textContent=warning||'ESTE É O CÓDIGO DA SUA SALA. Envie estes 8 caracteres ao outro jogador.';
    hint.dataset.warning=warning?'true':'false';
    urlInput.value=url;
    actions.hidden=false;
    copyCode.textContent='COPIAR MEU CÓDIGO';
    copyLink.textContent='COPIAR LINK';
    copyLink.disabled=!url;
    share.hidden=!url;
    if(url)share.href=whatsappShareUrl(url);
    else share.removeAttribute('href');
    card.dataset.roomState='created';
    return normalized;
  }
  function reset(){
    currentCode='';currentUrl='';
    codeNode.textContent='— — — — — — — —';
    codeNode.setAttribute('aria-label','Nenhuma sala criada');
    hint.textContent='Crie uma partida para receber o código exclusivo da SUA sala.';
    hint.dataset.warning='false';
    urlInput.value='';actions.hidden=true;
    copyCode.textContent='COPIAR MEU CÓDIGO';
    copyLink.textContent='COPIAR LINK';
    card.dataset.roomState='waiting';
  }
  reset();
  return {show,reset,get currentCode(){return currentCode;},get currentUrl(){return currentUrl;}};
}
